import numpy as np
from scipy.optimize import minimize

def solve_for_n(n):
    # Maximize sum(a_i^2) subject to sum(a_i^3) = 0 and a_i <= 2/sqrt(n)
    # This is equivalent to minimizing sum(-a_i^2)

    c = -np.ones(n)

    def objective(a):
        return -np.sum(a**2)

    def constraint(a):
        return np.sum(a**3)

    bounds = [(-10, 2.0/np.sqrt(n)) for _ in range(n)]

    cons = {'type': 'eq', 'fun': constraint}

    # Try multiple starting points because it's non-convex
    best_val = -float('inf')
    for _ in range(10):
        x0 = np.random.uniform(-2, 2/np.sqrt(n), n)
        res = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            if -res.fun > best_val:
                best_val = -res.fun

    return best_val

for n in [2, 3, 4, 5, 6, 7, 8, 9, 10, 18]:
    print(f"n={n}, max_S2={solve_for_n(n)}")

import numpy as np
from scipy.optimize import minimize

def solve_for_n_custom(n, starting_a):
    def objective(a):
        return -np.sum(a**2)

    def constraint(a):
        return np.sum(a**3)

    bounds = [(-10, 2.0/np.sqrt(n)) for _ in range(n)]
    cons = {'type': 'eq', 'fun': constraint}

    res = minimize(objective, starting_a, method='SLSQP', bounds=bounds, constraints=cons)
    return -res.fun if res.success else None

n = 9
# Attempt 1: k values of 2/sqrt(n) and (n-k) values of y
for k in range(1, n):
    x = 2.0/np.sqrt(n)
    y = -(k/(n-k))**(1/3) * x
    a_start = np.array([x]*k + [y]*(n-k))
    val = solve_for_n_custom(n, a_start)
    print(f"k={k}, a_start_S2={np.sum(a_start**2)}, result={val}")
